defmodule Seedling.Index do
  @moduledoc """
  Generates a discoverable NOTES.md from sorted docs/seedling-*.md fragments.
  `Seedling.Index.generate(root: "/app")` returns `{:ok, path}`. No node settings
  or modules are changed. Fragment writers own their own file; regeneration is explicit.
  """
  def render(opts \\ []) do
    root = Keyword.get(opts, :root, "/app")
    fragments = Path.wildcard(Path.join(root, "docs/seedling-*.md")) |> Enum.sort()

    Enum.reduce_while(
      fragments,
      {:ok,
       "# Seedling capability index\n\nGenerated by `Seedling.Index.generate/1` from docs/seedling-*.md.\n"},
      fn file, {:ok, acc} ->
        case File.read(file) do
          {:ok, text} ->
            {:cont,
             {:ok, acc <> "\n<!-- " <> Path.relative_to(file, root) <> " -->\n\n" <> text <> "\n"}}

          error ->
            {:halt, error}
        end
      end
    )
  end

  def generate(opts \\ []) do
    target = Path.join(Keyword.get(opts, :root, "/app"), "NOTES.md")
    tmp = target <> "." <> Base.encode16(:crypto.strong_rand_bytes(8)) <> ".tmp"

    try do
      with {:ok, text} <- render(opts),
           :ok <- File.write(tmp, text, [:sync]),
           :ok <- File.rename(tmp, target),
           do: {:ok, target}
    after
      File.rm(tmp)
    end
  end
end
